package android.graphics; public class PointF { public float x,y; public PointF(){} public PointF(float x,float y){set(x,y);} public PointF(Point p){set(p.x,p.y);} public void set(float x,float y){this.x=x;this.y=y;} public void set(PointF p){set(p.x,p.y);} public void offset(float x,float y){this.x+=x;this.y+=y;} public float length(){return length(x,y);} public static float length(float x,float y){return (float)Math.sqrt(x*x+y*y);} public boolean equals(Object o){return o instanceof PointF&&((PointF)o).x==x&&((PointF)o).y==y;} public int hashCode(){return (int)(x*31+y);} public String toString(){return "PointF("+x+", "+y+")";} }